/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */
export async function upsertSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  content: string,
  projectId: ProjectId | null,
): Promise<void> {
  const db = getDb();
  const indexedAt = toIsoTimestamp(new Date());

  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }

  db.insert(searchIndex)
    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/**
 * Substring match over the denormalised content column. Deliberately simple —
 * the index is a convenience layer, not a search engine, and the tenant filter
 * is what actually matters here.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
    // The index is denormalized and may be stale between writes or after a
    // partial rebuild. Enforce the live parent chain at read time as well.
    sql`(
      (${searchIndex.subjectKind} = 'project' AND EXISTS (
        SELECT 1 FROM projects p WHERE p.id = ${searchIndex.subjectId}
          AND p.org_id = ${input.orgId} AND p.archived_at IS NULL
      )) OR
      (${searchIndex.subjectKind} = 'issue' AND EXISTS (
        SELECT 1 FROM issues i JOIN projects p ON p.id = i.project_id AND p.org_id = i.org_id
        WHERE i.id = ${searchIndex.subjectId} AND i.org_id = ${input.orgId}
          AND i.archived_at IS NULL AND p.archived_at IS NULL
      )) OR
      (${searchIndex.subjectKind} = 'comment' AND EXISTS (
        SELECT 1 FROM comments c JOIN issues i ON i.id = c.issue_id AND i.org_id = c.org_id
          JOIN projects p ON p.id = i.project_id AND p.org_id = i.org_id
        WHERE c.id = ${searchIndex.subjectId} AND c.org_id = ${input.orgId}
          AND c.archived_at IS NULL AND i.archived_at IS NULL AND p.archived_at IS NULL
      ))
    )`,
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => row,
    (row) => ({ id: row.id, sortValue: row.indexedAt }),
  );
}

/** Replace one tenant's index atomically so readers never see a partial rebuild. */
export async function rebuildSearchDocuments(
  orgId: OrgId,
  documents: readonly { subjectKind: SearchSubjectKind; subjectId: string; projectId: ProjectId | null; content: string }[],
): Promise<void> {
  const db = getDb();
  db.transaction((tx) => {
    tx.delete(searchIndex).where(orgPredicate(searchIndex.orgId, orgId)).run();
    if (documents.length) tx.insert(searchIndex).values(documents.map((document) => ({
      id: newId(), orgId, ...document, indexedAt: toIsoTimestamp(new Date()),
    }))).run();
  });
}

export async function deleteProjectDocuments(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const db = getDb();
  db.delete(searchIndex).where(and(orgPredicate(searchIndex.orgId, orgId), eq(searchIndex.projectId, projectId))).run();
}

/** Recreate only documents whose complete parent chain is live after restore. */
export async function restoreLiveProjectDocuments(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const db = getDb();
  const project = db.select().from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId), isNull(projects.archivedAt))).get();
  if (!project) return;
  const liveIssues = db.select().from(issues).where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId), isNull(issues.archivedAt))).all();
  const stamp = toIsoTimestamp(new Date());
  for (const issue of liveIssues) {
    db.insert(searchIndex).values({ id: newId(), orgId, subjectKind: "issue", subjectId: issue.id, projectId, content: [issue.title, issue.description ?? ""].join("\n"), indexedAt: stamp }).onConflictDoNothing().run();
    const liveComments = db.select().from(comments).where(and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issue.id), isNull(comments.archivedAt))).all();
    for (const comment of liveComments) db.insert(searchIndex).values({ id: newId(), orgId, subjectKind: "comment", subjectId: comment.id, projectId, content: comment.body, indexedAt: stamp }).onConflictDoNothing().run();
  }
}

/** Drift alarm input: how many documents this org currently has indexed. */
export async function countIndexed(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

